/// <summary>
/// Trigger extension for InventOnhandStorage table to send business event after insert.
/// </summary>
[ExtensionOf(tableStr(InventOnhandStorage))]
internal final class METInventOnhandStorage_Extension
{
}

Method.Source:
/// <summary>
/// Inseert method override to send the Inventory On-hand Report business event after a record is inserted.
/// </summary>
public void insert()
{
    next insert();
    // Call the business event after the record is inserted.
    METInventOnhandStorageBusinessEvent::newFromParameters(
        this.TransactionId,
        this.ExecutionName,
        this.ExecutionTime).send();
}
